@Override
	public boolean doHurtTarget(ServerLevel serverLevel, Entity toAttack) {
		if (toAttack instanceof LivingEntity living && living.isBlocking()) {
			if (this.getMovementPattern().getState() == NagaMovementPattern.MovementState.CHARGE) {
				Vec3 motion = this.getDeltaMovement();
				toAttack.push(motion.x() * 1.5D, 0.5D, motion.z() * 1.5D);
				this.push(motion.x() * -1.25D, 0.5D, motion.z() * -1.25D);
				if (toAttack instanceof ServerPlayer player) {
					player.getUseItem().hurtAndBreak(5, player, player.getUsedItemHand());
					PacketDistributor.sendToPlayer(player, new MovePlayerPacket(motion.x() * 3.0D, motion.y() + 0.75D, motion.z() * 3.0D));
				}
				this.hurt(this.damageSources().generic(), 2.0F);
				this.level().playSound(null, toAttack.blockPosition(), SoundEvents.SHIELD_BLOCK.value(), SoundSource.PLAYERS, 1.0F, 0.8F + this.level().getRandom().nextFloat() * 0.4F);
				this.getMovementPattern().doDaze();
				return false;
			} else if (this.getMovementPattern().getState() == NagaMovementPattern.MovementState.STUNLESS_CHARGE) {
				if (toAttack instanceof ServerPlayer player) {
					player.getUseItem().hurtAndBreak(10, player, player.getUsedItemHand());
					player.getCooldowns().addCooldown(player.getUseItem(), 200);
					player.stopUsingItem();
					this.level().broadcastEntityEvent(player, (byte) 30);
				}
				living.hurt(this.damageSources().mobAttack(this), 4.0F);
				this.playSound(SoundEvents.FOX_BITE, 2.0F, 0.5F);
				this.getMovementPattern().doCircle();
				return false;
			}
		}
		if (!this.isDazed()) {
			boolean result = super.doHurtTarget(serverLevel, toAttack);

			if (result) {
				// charging, apply extra pushback
				toAttack.push(-Mth.sin((getYRot() * Mth.PI) / 180.0F) * 2.0F, 0.4F, Mth.cos((getYRot() * Mth.PI) / 180.0F) * 2.0F);
			}

			return result;
		}
		return false;
	}

@Override
    public void aiStep() {
        super.aiStep();
        if (playerStatueCooldown > 0) {
            playerStatueCooldown--;
        }
        LivingEntity attackTarget = this.getTarget();
        if (attackTarget != null) {
            boolean blindness = this.hasEffect(MobEffects.BLINDNESS) || attackTarget.hasEffect(MobEffects.BLINDNESS);
            if (!blindness && this.deathTime == 0 && attackTarget instanceof Mob && !(attackTarget instanceof Player)) {
                forcePreyToLook(attackTarget);
            }
            if (isEntityLookingAt(attackTarget, this, 0.4)) {
                this.getLookControl().setLookAt(attackTarget.getX(), attackTarget.getY() + (double) attackTarget.getEyeHeight(), attackTarget.getZ(), (float) this.getMaxHeadYRot(), (float) this.getMaxHeadXRot());
            }
        }


        if (attackTarget != null && isEntityLookingAt(this, attackTarget, 0.4) && isEntityLookingAt(attackTarget, this, 0.4) && !isBlindfolded(attackTarget)) {
            boolean blindness = this.hasEffect(MobEffects.BLINDNESS) || attackTarget.hasEffect(MobEffects.BLINDNESS) || attackTarget instanceof IBlacklistedFromStatues && !((IBlacklistedFromStatues) attackTarget).canBeTurnedToStone();
            if (!blindness && this.deathTime == 0) {
                if (this.getAnimation() != ANIMATION_SCARE) {
                    this.playSound(IafSoundRegistry.GORGON_ATTACK, 1, 1);
                    this.setAnimation(ANIMATION_SCARE);
                }
                if (this.getAnimation() == ANIMATION_SCARE) {
                    if (this.getAnimationTick() > 10) {
                        if (!level.isClientSide) {
                            if (playerStatueCooldown == 0) {
                                EntityStoneStatue statue = EntityStoneStatue.buildStatueEntity(attackTarget);
                                statue.absMoveTo(attackTarget.getX(), attackTarget.getY(), attackTarget.getZ(), attackTarget.getYRot(), attackTarget.getXRot());
                                if (!level.isClientSide) {
                                    level.addFreshEntity(statue);
                                }
                                statue.setYRot(attackTarget.getYRot());
                                statue.setYRot(attackTarget.getYRot());
                                statue.yHeadRot = attackTarget.getYRot();
                                statue.yBodyRot = attackTarget.getYRot();
                                statue.yBodyRotO = attackTarget.getYRot();
                                playerStatueCooldown = 40;
                                if (attackTarget instanceof Player) {

                                    attackTarget.hurt(IafDamageRegistry.causeGorgonDamage(this), Integer.MAX_VALUE);
                                } else {
                                    attackTarget.remove(RemovalReason.KILLED);
                                }
                                this.setTarget(null);

                            }
                        }
                    }
                }
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
            super.tick();
            LivingEntity target = EntityFarseer.this.getTarget();
            if (laserCooldown > 0) {
                laserCooldown--;
            }
            timeSinceLastSuccessfulAttack++;
            if (timeSinceLastSuccessfulAttack > 100) {
                timeSinceLastSuccessfulAttack = 0;
                attackDecision = !attackDecision;
            }
            if (target != null) {
                double dist = EntityFarseer.this.distanceTo(target);
                boolean canLaserHit = willLaserHit(target);
                if (this.laserCooldown == 0 && attackDecision && canLaserHit && dist > 2F) {
                    EntityFarseer.this.setAngry(true);
                    EntityFarseer.this.entityData.set(LASER_ENTITY_ID, target.getId());
                    if(laserUseTime == 0){
                        EntityFarseer.this.playSound(AMSoundRegistry.FARSEER_BEAM.get(), EntityFarseer.this.getSoundVolume(), EntityFarseer.this.getVoicePitch());
                    }
                    laserUseTime++;
                    if (laserUseTime > LASER_ATTACK_DURATION) {
                        laserUseTime = 0;
                        if (canLaserHit) {
                            float healthTenth = target.getMaxHealth() * 0.1F;
                            if(target.hurt(AMDamageTypes.causeFarseerDamage(EntityFarseer.this), random.nextInt(2) + Math.max(6, healthTenth)) && !target.isAlive()){
                                AlexsMobs.sendMSGToAll(new MessageSendVisualFlagFromServer(target.getId(), 87));
                            }
                            timeSinceLastSuccessfulAttack = 0;
                        }
                        if (lasersShot++ > 5) {
                            lasersShot = 0;
                            laserCooldown = 80 + random.nextInt(40);
                            EntityFarseer.this.entityData.set(LASER_ENTITY_ID, -1);
                            attackDecision = EntityFarseer.this.getRandom().nextBoolean();
                        }
                    }
                    EntityFarseer.this.entityData.set(LASER_ATTACK_LVL, laserUseTime);
                    EntityFarseer.this.lookAt(target, 180F, 180F);
                    if (dist < 17F && canLaserHit) {
                        EntityFarseer.this.getNavigation().stop();
                    } else {
                        EntityFarseer.this.getNavigation().moveTo(target, 1F);
                    }
                    EntityFarseer.this.entityData.set(MELEEING, false);
                } else {
                    if (!canLaserHit && dist > 10) {
                        EntityFarseer.this.setAngry(false);
                    }
                    if (EntityFarseer.this.hasLaser()) {
                        EntityFarseer.this.entityData.set(LASER_ENTITY_ID, -1);
                    }
                    EntityFarseer.this.entityData.set(MELEEING, dist < 4F);
                    if (dist < 4F) {
                        timeSinceLastSuccessfulAttack = 0;
                    } else {
                        EntityFarseer.this.getNavigation().moveTo(target, 1F);
                        EntityFarseer.this.moveControl.setWantedPosition(target.getX(), target.getEyeY(), target.getZ(), 1F);
                    }
                }
            }
        }

@Override
        public boolean canUse() {
            return EntityFarseer.this.getTarget() != null && EntityFarseer.this.getTarget().isAlive();
        }

public void stop() {
            this.lasersShot = 0;
            this.laserCooldown = 0;
            this.laserUseTime = 0;
            attackDecision = EntityFarseer.this.getRandom().nextBoolean();
            EntityFarseer.this.entityData.set(LASER_ENTITY_ID, -1);
            timeSinceLastSuccessfulAttack = 0;
            EntityFarseer.this.setAngry(false);
        }

private boolean willLaserHit(LivingEntity target) {
            Vec3 vec = EntityFarseer.this.calculateLaserHit(target.getEyePosition());
            return vec.distanceTo(target.getEyePosition()) < 1F && EntityFarseer.this.canUseLaser();
        }

private Vec3 calculateLaserHit(Vec3 target) {
        Vec3 eyes = new Vec3(this.getX(), this.getEyeY(), this.getZ());
        HitResult hitResult = this.level().clip(new ClipContext(eyes, target, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
        return hitResult.getLocation();
    }

@Override
	public void tick() {
		super.tick();

		Entity riding = getVehicle();
		if(riding != null)
			rideTime++;
		else
			rideTime = 0;

		if(eatCooldown > 0)
			eatCooldown--;

		if(angeryTicks > 0 && isAlive()) {
			angeryTicks--;

			if(onGround()) {
				int dangerRange = 3;
				double x = getX() + getBbWidth() / 2;
				double y = getY();
				double z = getZ() + getBbWidth() / 2;

				if(level() instanceof ServerLevel serverLevel) {
					if(angeryTicks == 3)
						playSound(QuarkSounds.ENTITY_TORETOISE_ANGRY, 1F, 0.2F);
					else if(angeryTicks == 0) {
						serverLevel.sendParticles(ParticleTypes.CLOUD, x, y, z, 200, dangerRange, 0.5, dangerRange, 0);
						gameEvent(GameEvent.ENTITY_ACTION);
					}
				}

				if(angeryTicks == 0) {
					AABB hurtAabb = new AABB(x - dangerRange, y - 1, z - dangerRange, x + dangerRange, y + 1, z + dangerRange);
					List<LivingEntity> hurtMeDaddy = level().getEntitiesOfClass(LivingEntity.class, hurtAabb, e -> !(e instanceof Toretoise));

					LivingEntity aggressor = lastAggressor == null ? this : lastAggressor;
					DamageSource damageSource = damageSources().mobAttack(aggressor);
					for(LivingEntity e : hurtMeDaddy) {
						DamageSource useSource = damageSource;
						if(e == aggressor)
							useSource = damageSources().mobAttack(this);
						if(e instanceof Player player && level().getDifficulty() == Difficulty.PEACEFUL){
							player.push(0, 0.25, 0);
							//give the player slight upwards knocback so there's some sort of feedback without hurting them in peaceful
						}

						e.hurt(useSource, 4 + level().getDifficulty().ordinal());
					}
				}
			}
		}

		if(level() instanceof ServerLevel serverLevel) {
			int ore = getOreType();
			if(ore != 0)
				breakOre: {
					AABB ourBoundingBox = getBoundingBox();
					BlockPos min = BlockPos.containing(Math.round(ourBoundingBox.minX), Math.round(ourBoundingBox.minY), Math.round(ourBoundingBox.minZ));
					BlockPos max = BlockPos.containing(Math.round(ourBoundingBox.maxX), Math.round(ourBoundingBox.maxY), Math.round(ourBoundingBox.maxZ));

					for(int ix = min.getX(); ix <= max.getX(); ix++)
						for(int iy = min.getY(); iy <= max.getY(); iy++)
							for(int iz = min.getZ(); iz <= max.getZ(); iz++) {
								BlockPos test = new BlockPos(ix, iy, iz);
								BlockState state = level().getBlockState(test);
								if(state.getBlock() == Blocks.MOVING_PISTON) {
									BlockEntity tile = level().getBlockEntity(test);
									if(tile instanceof PistonMovingBlockEntity piston && piston.isExtending()) {
										BlockState pistonState = piston.getMovedState();
										if(pistonState.is(BREAKS_TORETOISE_ORE)) {
											if(!pistonState.hasProperty(RodBlock.FACING) || pistonState.getValue(RodBlock.FACING) == piston.getMovementDirection()) {
												dropOre(ore, new LootParams.Builder(serverLevel)
														.withParameter(LootContextParams.TOOL, new ItemStack(Items.IRON_PICKAXE)));
												break breakOre;
											}
										}
									}
								}
							}
				}
		}
	}

@Override
	public boolean hurt(DamageSource source, float amount) {
		Entity e = source.getDirectEntity();
		int ore = getOreType();

		if(e instanceof LivingEntity living) {
			ItemStack held = living.getMainHandItem();

			if(ore != 0 && held.getItem().canPerformAction(held, ItemAbilities.PICKAXE_DIG)) { //TODO: IForgeItem
				if(level() instanceof ServerLevel serverLevel) {
					if(held.isDamageableItem() && e instanceof Player player)
						held.hurtAndBreak(1, player, EquipmentSlot.MAINHAND);

					LootParams.Builder lootBuilder = new LootParams.Builder(serverLevel)
							.withParameter(LootContextParams.TOOL, held);
					if(living instanceof Player player)
						lootBuilder.withLuck(player.getLuck());
					dropOre(ore, lootBuilder);

					if(living instanceof ServerPlayer sp) {
						ToretoiseModule.mineToretoiseTrigger.trigger(sp);
						if(isTamed)
							ToretoiseModule.mineFedToretoiseTrigger.trigger(sp);
					}
				}

				return false;
			}

			if(angeryTicks == 0) {
				angeryTicks = ANGERY_TIME;
				lastAggressor = living;
			}
		}

		return super.hurt(source, amount);
	}

@Override
	public void addAdditionalSaveData(@NotNull CompoundTag compound) {
		super.addAdditionalSaveData(compound);
		compound.putBoolean(TAG_TAMED, isTamed);
		compound.putInt(TAG_ORE, getOreType());
		compound.putInt(TAG_EAT_COOLDOWN, eatCooldown);
		compound.putInt(TAG_ANGERY_TICKS, angeryTicks);
	}

@Override
	public void readAdditionalSaveData(@NotNull CompoundTag compound) {
		super.readAdditionalSaveData(compound);
		isTamed = compound.getBoolean(TAG_TAMED);
		entityData.set(ORE_TYPE, compound.getInt(TAG_ORE));
		eatCooldown = compound.getInt(TAG_EAT_COOLDOWN);
		angeryTicks = compound.getInt(TAG_ANGERY_TICKS);
	}

public void rideTick() {
        Entity entity = this.getVehicle();
        if (this.isPassenger() && !entity.isAlive()) {
            this.stopRiding();
        } else {
            this.setDeltaMovement(0, 0, 0);
            this.tick();
            if (this.isPassenger()) {
                attachTime++;
                Entity mount = this.getVehicle();
                if (mount instanceof LivingEntity) {
                    passengerIndex = mount.getPassengers().indexOf(this);
                    this.yBodyRot = ((LivingEntity) mount).yBodyRot;
                    this.setYRot( ((LivingEntity) mount).getYRot());
                    this.yHeadRot = ((LivingEntity) mount).yHeadRot;
                    this.yRotO = ((LivingEntity) mount).yHeadRot;
                    float radius = mount.getBbWidth();
                    float angle = (Maths.STARTING_ANGLE * (((LivingEntity) mount).yBodyRot + passengerIndex * 90F));
                    double extraX = radius * Mth.sin(Mth.PI + angle);
                    double extraZ = radius * Mth.cos(angle);
                    this.setPos(mount.getX() + extraX, Math.max(mount.getY() + mount.getEyeHeight() * 0.25F, mount.getY()), mount.getZ() + extraZ);
                    if (!mount.isAlive() || mount instanceof Player && ((Player) mount).isCreative()) {
                        this.removeVehicle();
                    }
                    this.setPhagePitch(0F);
                    if (!this.level().isClientSide && attachTime > 15) {
                        LivingEntity target = (LivingEntity) mount;
                        float dmg = 1F;
                        if (target.getHealth() > target.getMaxHealth() * 0.2F) {
                            dmg = 6F;
                        }
                        if ((target.getHealth() < 1.5D || mount.hurt(this.damageSources().mobAttack(this), dmg)) && mount instanceof LivingEntity) {
                            dismountCooldown = 100;
                            if (mount instanceof EnderMan) {
                                this.setMissingEye(false);
                                this.gameEvent(GameEvent.EAT);
                                this.playSound(SoundEvents.ENDER_EYE_DEATH, this.getSoundVolume(), this.getVoicePitch());
                                this.heal(5);
                                ((EnderMan) mount).addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 400));
                                this.fleeAfterStealTime = 400;
                                this.setFlying(true);
                                this.angryEnderman = (PathfinderMob) mount;
                            } else {
                                if (random.nextInt(3) == 0) {
                                    if (!this.isMissingEye()) {
                                        if (target.getEffect(AMEffectRegistry.ENDER_FLU.get()) == null) {
                                            target.addEffect(new MobEffectInstance(AMEffectRegistry.ENDER_FLU.get(), 12000));
                                        } else {
                                            MobEffectInstance inst = target.getEffect(AMEffectRegistry.ENDER_FLU.get());
                                            int duration = 12000;
                                            int level = 0;
                                            if (inst != null) {
                                                duration = inst.getDuration();
                                                level = inst.getAmplifier();
                                            }
                                            target.removeEffect(AMEffectRegistry.ENDER_FLU.get());
                                            target.addEffect(new MobEffectInstance(AMEffectRegistry.ENDER_FLU.get(), duration, Math.min(level + 1, 4)));
                                        }
                                        this.heal(5);
                                        this.gameEvent(GameEvent.ENTITY_ROAR);
                                        this.playSound(SoundEvents.ITEM_BREAK, this.getSoundVolume(), this.getVoicePitch());
                                        this.setMissingEye(true);
                                    }
                                    if (!this.level().isClientSide) {
                                        this.setTarget(null);
                                        this.setLastHurtMob(null);
                                        this.setLastHurtByMob(null);
                                        this.goalSelector.getRunningGoals().forEach(Goal::stop);
                                        this.targetSelector.getRunningGoals().forEach(Goal::stop);
                                    }
                                }
                            }
                        }
                        if (((LivingEntity) mount).getHealth() <= 0 || this.fleeAfterStealTime > 0 || this.isMissingEye() && !(mount instanceof EnderMan) || !this.isMissingEye() && mount instanceof EnderMan) {
                            this.removeVehicle();
                            this.setTarget(null);
                            dismountCooldown = 100;
                            AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                            this.setFlying(true);
                        }
                    }
                }

            }
        }

    }

public void tick() {
        int currentTemp = logic.getTemperatureAsInt();

        if (shouldSyncNow()) {
            // large temperature delta: sync immediately
            this.syncedTemp = currentTemp;
            syncTimer = -1;
        } else if (currentTemp != syncedTemp) {
            // small temperature delta: schedule a sync to happen in 60 ticks, unless one is already scheduled
            if (syncTimer == -1) syncTimer = SYNC_RATE;
            pendingTemp = currentTemp;
        }

        if (syncTimer >= 0) {
            if (--syncTimer == -1) {
                this.syncedTemp = pendingTemp;
            }
        }
    }

private boolean shouldSyncNow() {
        int currentTemp = logic.getTemperatureAsInt();

        if (syncedTemp < 0) return true; // initial sync

        int delta = Math.abs(syncedTemp - currentTemp);

        if (currentTemp < 73) {
            return false;
        } else if (currentTemp < 473) {
            return delta >= 10;
        } else if (currentTemp < 873) {
            return delta >= 30;
        } else if (currentTemp < 1473) {
            return delta >= 80;
        } else {
            return false;
        }
    }

@Override
    public void tick() {
        super.tick();

        if (tickCount == 1) {
            logic.initializeAmbientTemperature(level(), getBlockPos());
        }

        if (!getWorld().isClientSide) {
            byte newStatus = IDLE;
            if (logic.getTemperature() > MIN_COOKING_TEMP) {
                newStatus = doCooking();
            } else if (logic.getTemperature() < HeatFrameCoolingRecipeImpl.getMaxThresholdTemp(getWorld())) {
                newStatus = doCooling();
            }
            setStatus(newStatus);
            if (newStatus == IDLE) {
                double delta = logic.getTemperature() - logic.getAmbientTemperature();
                if (delta > 1) {
                    logic.addHeat(-0.1);
                } else if (delta < -1) {
                    logic.addHeat(0.1);
                }
            }
            syncedTemperature.tick();
            setSyncedTemperature(syncedTemperature.getSyncedTemp());
        } else {
            // client
            if ((tickCount & 0x3) == 0) {
                byte status = getStatus();
                switch (status) {
                    case COOKING -> ClientUtils.emitParticles(level(), getBlockPos(), level().random.nextInt(4) == 0 ? ParticleTypes.FLAME : ParticleTypes.SMOKE);
                    case COOLING -> ClientUtils.emitParticles(level(), getBlockPos(), ParticleTypes.SPIT);
                }
            }
        }
    }

private void setSyncedTemperature(int temperature) {
        getEntityData().set(TEMPERATURE, temperature);
    }
